// src/main.ts
var CopilotPlugin = class extends import_obsidian8.Plugin {
  constructor() {
    super(...arguments);
    this.version = "1.0.9";
  }
  async onload() {
    this.settingsTab = new CopilotPluginSettingTab_default(this.app, this);
    this.addSettingTab(this.settingsTab);
    await this.settingsTab.loadSettings();
    this.statusBar = new StatusBar_default(this);
    Logger_default.getInstance().setDebug(this.settings.debug);
    if (!File_default.doesFolderExist(Vault_default.getCopilotPath(this.app, this.version))) {
      await File_default.createFolder(
        Vault_default.getCopilotResourcesPath(this.app, this.version)
      );
      await File_default.createFile(
        Vault_default.getAgentPath(this.app, this.version),
        agent_default
      );
      await File_default.createFile(
        Vault_default.get100kPath(this.app, this.version),
        cl100k_base_default
      );
      await File_default.createFile(
        Vault_default.get200kPath(this.app, this.version),
        o200k_base_default
      );
      await File_default.removeOldCopilotFolders(
        this.version,
        Vault_default.getPluginPath(this.app)
      );
    }
    if (this.settings.nodePath === DEFAULT_SETTINGS.nodePath) {
      new import_obsidian8.Notice(
        "Please set the path to your node executable in the settings."
      );
    }
    this.copilotAgent = new CopilotAgent_default(this);
    if (this.settingsTab.isCopilotEnabled() && this.settings.nodePath !== DEFAULT_SETTINGS.nodePath)
      await this.copilotAgent.setup();
    this.eventManager = new EventManager_default(this);
    this.eventManager.registerEvents();
    this.cmExtensionManager = new ExtensionManager_default(this);
    this.registerEditorExtension(this.cmExtensionManager.getExtensions());
    const file = this.app.workspace.getActiveFile();
    if (file) {
      Cacher_default.getInstance().setCurrentFilePath(
        Vault_default.getBasePath(this.app),
        file.path
      );
    }
  }
  onunload() {
    var _a;
    (_a = this.copilotAgent) == null ? void 0 : _a.stopAgent();
    this.statusBar = null;
  }
};
